contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // call drive: caller provides a receiver and amount; this function must be invoked by SOME caller
    // It will attempt to have c send 'amount' to 'receiver' and then assert that the balance of c
    // decreased only if the caller is the owner. Since we cannot read owner, we express the rule as:
    // If the current msg.sender is not the original deployer of c, then calling sendTo must revert (so balance unchanged).
    // We implement this by requiring that either the call succeeds and msg.sender is owner (allowed on P),
    // or the call reverts (disallowed on M where anyone can call and succeed). We detect success by observing
    // c balance before/after and using a low-level call to catch revert.

    // Note: state-changing calls on c must be top-level. We perform a low-level call to c.sendTo via ABI.
    function testSend(address payable receiver, uint256 amount) public {
        require(receiver != address(0));
        require(amount > 0);

        // record balance before
        uint256 before = address(c).balance;

        // perform the call; this is a state-changing interaction with c and must be top-level
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        uint256 after = address(c).balance;

        // If the call succeeded (ok==true) then c's balance must have decreased by at least amount.
        // On the original contract P only the owner can make it succeed; on mutant M anyone can succeed.
        // Therefore the property: either the call reverted (ok==false) OR the balance decreased by >= amount.
        // This single assert captures the distinguishing behavior.
        assert(!ok || before - after >= amount);
    }

    // allow the test contract to hold ether if needed
    receive() external payable {}
}

